#### 2a: meff — effective mass factor (sweph.c:5967)

101-entry lookup table sorted descending by r. Boundary clamping. Linear interpolation.

```rust
use crate::constants::*;

const EFF_ARR: [(f64, f64); 101] = [
    (1.000, 1.000000), (0.990, 0.999979), (0.980, 0.999940),
    // ... full table from c-ref-calc.md (101 entries) ...
    (0.010, 0.002767), (0.000, 0.000000),
];

pub fn meff(r: f64) -> f64 {
    if r <= 0.0 { return 0.0; }
    if r >= 1.0 { return 1.0; }
    // Linear search forward (table descending) until eff_arr[i].0 <= r
    let i = EFF_ARR.iter().position(|(ri, _)| *ri <= r).unwrap();
    let (r0, m0) = EFF_ARR[i - 1]; // higher r
    let (r1, m1) = EFF_ARR[i];     // lower r  
    let f = (r - r0) / (r1 - r0);
    m0 + f * (m1 - m0)
}
```

#### 2b: aberr_light — Lorentz aberration (sweph.c:3699)

Position-only correction. Takes earth velocity (AU/day), converts to units of c.

```rust
pub fn aberr_light(xx: &mut [f64; 6], earth_vel: &[f64; 3]) {
    // Convert earth velocity to units of c
    // C evaluation order: xe[i+3] / (24*3600) / CLIGHT * AUNIT
    let mut v = [0.0; 3];
    let mut v2 = 0.0;
    for i in 0..3 {
        v[i] = earth_vel[i] / 86400.0 / CLIGHT * AUNIT;
        v2 += v[i] * v[i];
    }

    let ru = (xx[0] * xx[0] + xx[1] * xx[1] + xx[2] * xx[2]).sqrt();
    let b_1 = (1.0 - v2).sqrt(); // 1/γ

    let mut f1 = 0.0;
    for i in 0..3 { f1 += xx[i] * v[i]; }
    f1 /= ru;
    let f2 = 1.0 + f1 / (1.0 + b_1);

    for i in 0..3 {
        xx[i] = (b_1 * xx[i] + f2 * ru * v[i]) / (1.0 + f1);
    }
    // xx[3..6] (speed) untouched — caller handles speed correction
}
```

#### 2c: deflect_light — GR light bending (sweph.c:3743)

Position-only correction. Takes pre-computed earth heliocentric and planet heliocentric positions (3-element each).

```rust
pub fn deflect_light(
    xx: &mut [f64; 6],
    earth_helio: &[f64; 3],
    planet_helio: &[f64; 3],
) {
    // U = planet geocentric, E = earth helio, Q = planet helio
    let ru = (xx[0]*xx[0] + xx[1]*xx[1] + xx[2]*xx[2]).sqrt();
    let re = (earth_helio[0]*earth_helio[0] + earth_helio[1]*earth_helio[1] + earth_helio[2]*earth_helio[2]).sqrt();
    let rq = (planet_helio[0]*planet_helio[0] + planet_helio[1]*planet_helio[1] + planet_helio[2]*planet_helio[2]).sqrt();

    let u = [xx[0]/ru, xx[1]/ru, xx[2]/ru];
    let e = [earth_helio[0]/re, earth_helio[1]/re, earth_helio[2]/re];
    let q = [planet_helio[0]/rq, planet_helio[1]/rq, planet_helio[2]/rq];

    let uq = u[0]*q[0] + u[1]*q[1] + u[2]*q[2];
    let ue = u[0]*e[0] + u[1]*e[1] + u[2]*e[2];
    let qe = q[0]*e[0] + q[1]*e[1] + q[2]*e[2];

    // meff: smooth singularity near solar limb
    let sina = (1.0 - ue * ue).sqrt();
    let sin_sunr = SUN_RADIUS / re;
    let meff_fact = if sina < sin_sunr { meff(sina / sin_sunr) } else { 1.0 };

    // Deflection (Explanatory Supplement formula)
    let g1 = 2.0 * HELGRAVCONST * meff_fact / CLIGHT / CLIGHT / AUNIT / re;
    let g2 = 1.0 + qe;

    for i in 0..3 {
        xx[i] = ru * (u[i] + g1 / g2 * (uq * e[i] - ue * q[i]));
    }
    // xx[3..6] (speed) untouched — caller handles speed correction
}
```

